pack_path, idx_list, out_repo, skip_list = sys.argv[1:5]
data = open(pack_path, 'rb').read()
entries = sorted((int(l.split()[0]), l.split()[1]) for l in open(idx_list))
by_off = {off: sha for off, sha in entries}
by_sha = {sha: off for off, sha in entries}
offsets = [e[0] for e in entries] + [len(data) - 20]
next_of = {entries[i][0]: offsets[i + 1] for i in range(len(entries))}
skip = set(l.strip() for l in open(skip_list) if l.strip())  # already present in out_repo (orphan pack)
TYPES = {1: 'commit', 2: 'tree', 3: 'blob', 4: 'tag'}

def parse_header(pos):
    c = data[pos]; pos += 1
    t = (c >> 4) & 7; size = c & 15; shift = 4
    while c & 0x80:
        c = data[pos]; pos += 1
        size |= (c & 0x7f) << shift; shift += 7
    return t, size, pos

def parse_ofs(pos):
    c = data[pos]; pos += 1
    off = c & 0x7f
    while c & 0x80:
        c = data[pos]; pos += 1
        off = ((off + 1) << 7) | (c & 0x7f)
    return off, pos

def apply_delta(base, delta):
    pos = 0
    def varint():
        nonlocal pos
        v = 0; shift = 0
        while True:
            c = delta[pos]; pos += 1
            v |= (c & 0x7f) << shift; shift += 7
            if not (c & 0x80): break
        return v
    bsize = varint(); rsize = varint()
    if bsize != len(base): raise Exception(f'delta base size {bsize} != {len(base)}')
    out = bytearray()
    while pos < len(delta):
        c = delta[pos]; pos += 1
        if c & 0x80:
            cp_off = 0; cp_size = 0
            if c & 0x01: cp_off |= delta[pos]; pos += 1
            if c & 0x02: cp_off |= delta[pos] << 8; pos += 1
            if c & 0x04: cp_off |= delta[pos] << 16; pos += 1
            if c & 0x08: cp_off |= delta[pos] << 24; pos += 1
            if c & 0x10: cp_size |= delta[pos]; pos += 1
            if c & 0x20: cp_size |= delta[pos] << 8; pos += 1
            if c & 0x40: cp_size |= delta[pos] << 16; pos += 1
            if cp_size == 0: cp_size = 0x10000
            out += base[cp_off:cp_off + cp_size]
        elif c:
            out += delta[pos:pos + c]; pos += c
        else:
            raise Exception('bad delta op 0')
    if len(out) != rsize: raise Exception('delta result size mismatch')
    return bytes(out)

cache = {}
def sha_of(t, content):
    return hashlib.sha1(f'{t} {len(content)}\0'.encode() + content).hexdigest()

def external(sha):
    t = subprocess.run(['git', '-C', out_repo, 'cat-file', '-t', sha], capture_output=True, text=True)
    if t.returncode != 0: raise Exception(f'base {sha} unavailable anywhere')
    c = subprocess.run(['git', '-C', out_repo, 'cat-file', t.stdout.strip(), sha], capture_output=True)
    return t.stdout.strip(), c.stdout

def get_object(sha, via=None):
    if sha in cache: return cache[sha]
    if sha in by_sha:
        try:
            r = read_entry(by_sha[sha])
            cache[sha] = r; return r
        except Exception as e:
            pass
    r = external(sha)
    cache[sha] = r
    return r

def read_entry(off):
    sha = by_off[off]
    t, size, pos = parse_header(off)
    base_ref = None
    if t == 6:
        rel, pos = parse_ofs(pos); base_ref = by_off[off - rel]
    elif t == 7:
        base_ref = data[pos:pos + 20].hex(); pos += 20
    region = data[pos:next_of[off]]
    d = zlib.decompressobj()
    out = d.decompress(region)
    if not d.eof: raise Exception('truncated zlib')
    if len(out) != size: raise Exception('size mismatch')
    if t in TYPES:
        rt, content = TYPES[t], out
    else:
        bt, bcontent = get_object(base_ref)
        rt, content = bt, apply_delta(bcontent, out)
    if sha_of(rt, content) != sha: raise Exception(f'sha mismatch: got {sha_of(rt, content)}')
    return rt, content

def write_loose(t, content):
    full = f'{t} {len(content)}\0'.encode() + content
    sha = hashlib.sha1(full).hexdigest()
    path = os.path.join(out_repo, 'objects', sha[:2], sha[2:])
    if not os.path.exists(path):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f: f.write(zlib.compress(full, 9))
    return sha

ok = 0; failed = []
for off, sha in entries:
    try:
        t, content = read_entry(off)
        cache[sha] = (t, content)
        if sha not in skip:
            write_loose(t, content)
        ok += 1
    except Exception as e:
        failed.append((off, sha, str(e), 'in_orphan' if sha in skip else 'ONLY_IN_BAD_PACK'))
print(f'recovered {ok}/{len(entries)}')
for f in failed:
    print('FAILED', *f)
