import zlib, hashlib, sys, os
path, sha, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
raw = open(path, 'rb').read()

def check(buf):
    try:
        out = zlib.decompress(buf)
    except Exception:
        return None
    if hashlib.sha1(out).hexdigest() == sha:
        return out
    return None

def report_partial():
    d = zlib.decompressobj()
    got = b''
    for i in range(0, len(raw)):
        try:
            got += d.decompress(raw[i:i+1])
        except Exception as e:
            return i, got, str(e)
    return len(raw), got, 'no error (eof=%s)' % d.eof

pos, got, err = report_partial()
print(f'{sha}: {len(raw)} bytes; streaming inflate fails at input byte {pos} with "{err}", produced {len(got)} bytes')
hdr_end = got.find(b'\0')
print('  header:', got[:hdr_end] if hdr_end >= 0 else got[:30])

# longest zero run
best = cur = 0
for b in raw:
    cur = cur + 1 if b == 0 else 0
    best = max(best, cur)
print('  longest zero run:', best)

if check(raw):
    print('  already OK?!'); sys.exit()
for i in range(len(raw)):
    orig = raw[i]
    b = bytearray(raw)
    for v in range(256):
        if v == orig: continue
        b[i] = v
        r = check(bytes(b))
        if r is not None:
            print(f'  FIXED single byte at {i}: {orig:02x} -> {v:02x}')
            open(os.path.join(outdir, sha), 'wb').write(bytes(b))
            sys.exit()
# try single byte deletion / insertion
for i in range(len(raw)):
    b = raw[:i] + raw[i+1:]
    if check(b) is not None:
        print(f'  FIXED by deleting byte at {i}'); open(os.path.join(outdir, sha), 'wb').write(b); sys.exit()
for i in range(len(raw) + 1):
    for v in range(256):
        b = raw[:i] + bytes([v]) + raw[i:]
        if check(b) is not None:
            print(f'  FIXED by inserting {v:02x} at {i}'); open(os.path.join(outdir, sha), 'wb').write(b); sys.exit()
print('  NO single-byte fix found')
